import { join } from "node:path";

/**
 * Where the built search index lives.
 *
 * Gitignored and generated by `npm run build:index`, never committed — a
 * committed index is a thing that can be stale, and "a fresh clone has nothing
 * that can be out of date" is a property worth keeping. `next.config.ts` traces
 * this path into the serverless bundle; without that the deployed app boots with
 * no index at all.
 */
export const INDEX_DIR = join(process.cwd(), "data");
export const INDEX_PATH = join(INDEX_DIR, "kb.sqlite");
